  GX0: 8, GX1: 128, GZ0: 0, GZ1: 120,
  TER_N: 5, TER_DEPTH: 24, TER_Y: [7, 11, 15, 19, 23],
  PIER_W: 1.8, ARCH_SPAN: 2.6, ARCH_H: 3.0, VAULT_DEPTH: 9,
  STAIR_X0: 8, STAIR_X1: 17, FLIGHT: 16, LANDING: 8,
  STRIP_W: 3, STRIP_X0: 5,
  HOUSE_X0: 0, HOUSE_X1: 8, HOUSE_Z0: 100, HOUSE_Z1: 120, HOUSE_TOP: 29,
