// (an arch is drawn in ARC_N lengths; r8, ROOM MADE: from bay ARC_FAR_J on, 44 m and more from the stair, in ARC_FAR)
const ARC_N = 10, ARC_FAR_J = 9, ARC_FAR = 6;
// one front at z0, standing from yBase to yTop: piers (0.25 m proud), arches, rings, cornice, lip, and the vaults
// behind. A vault is lit from its mouth: the barrel, jambs and floor fall from a mouth tone to a back tone, the back
// wall stands in light thrown up from the floor (brighter low), and things stand in most of them.
async function archedFront(B, n, z0, yBase, yTop, tone, yieldNow) {
  const r = M.ARCH_SPAN / 2, ys = yBase + M.ARCH_H - r, zp = z0 - 0.25, zDeep = z0 + M.VAULT_DEPTH;
  const wall = shade(COL.brick, tone), pier = shade(COL.brickPale, tone), ring = shade(COL.brickRed, tone * 0.92), N = [0, 0, -1], S = [0, 0, 1];
  const mouth = shade(COL.brick, 0.9 * tone), deep = shade(COL.brick, 0.42), floorM = shade(COL.pave, 1.25), floorMid = shade(COL.pave, 0.8), floorB = shade(COL.pave, 0.42), backLo = shade(COL.brickPale, 0.7), backHi = shade(COL.brick, 0.36);
  for (let j = 0; j < BAYS; j++) {
    const xp = FRONT_X0 + j * BAY, xa = xp + M.PIER_W, xc = xa + r, free = j === 0, zb = free ? z0 + FREE_ARCH_D : zDeep, inB = free ? mouth : deep;
    // the pier, proud of the wall, with a plinth and a cap course (the first is the end pier by the stair: END_PIER)
    if (free) endPier(B, xp, xa, z0, zb, yBase, yTop, pier);
    else { B.box(xp, yBase, zp, xa, yTop - 0.35, z0, pier, K.BRICK, 'xXz');
      B.box(xp - 0.08, yBase, zp - 0.1, xa + 0.08, yBase + 0.45, z0, shade(pier, 0.9), K.BRICK, 'xXYz'); }
    B.box(xp - 0.06, ys - 0.12, zp - 0.07, xa + 0.06, ys + 0.1, z0, shade(pier, 1.06), K.BRICK, 'xXyYz');
    // the wall over the arch, in upright strips from the arch's curve to the cornice; the ring round the arch
    const arcN = j < ARC_FAR_J ? ARC_N : ARC_FAR;
    for (let i = 0; i < arcN; i++) {
      const a0 = Math.PI - (i * Math.PI) / arcN, a1 = Math.PI - ((i + 1) * Math.PI) / arcN, am = (a0 + a1) / 2;
      const x0 = xc + r * Math.cos(a0), y0 = ys + r * Math.sin(a0), x1 = xc + r * Math.cos(a1), y1 = ys + r * Math.sin(a1);
      B.quad([x0, y0, z0], [x1, y1, z0], [x1, yTop - 0.35, z0], [x0, yTop - 0.35, z0], wall, K.BRICK, N);
      const rr = r + BRICK.L, X0 = xc + rr * Math.cos(a0), Y0 = ys + rr * Math.sin(a0), X1 = xc + rr * Math.cos(a1), Y1 = ys + rr * Math.sin(a1);
      B.quad([x0, y0, z0 - 0.09], [x1, y1, z0 - 0.09], [X1, Y1, z0 - 0.09], [X0, Y0, z0 - 0.09], ring, K.RING, N);
      B.quad([X0, Y0, z0 - 0.09], [X1, Y1, z0 - 0.09], [X1, Y1, z0], [X0, Y0, z0], ring, K.RING, [Math.cos(am), Math.sin(am), 0]);
      // the barrel: bright at its mouth, falling to the back tone a third of the way in
      const inn = [-Math.cos(am), -Math.sin(am), 0], zm = free ? zb : z0 + 3;
      B.quad([x0, y0, z0 - 0.09], [x1, y1, z0 - 0.09], [x1, y1, zm], [x0, y0, zm], [mouth, mouth, inB, inB], K.BRICK, inn);
      if (!free) B.quad([x0, y0, zm], [x1, y1, zm], [x1, y1, zb], [x0, y0, zb], inB, K.BRICK, inn);
      if (free) B.quad([x0, y0, zb], [x1, y1, zb], [x1, yTop - 0.35, zb], [x0, yTop - 0.35, zb], wall, K.BRICK, S);
    }
    // jambs, floor and back wall of the vault
    for (const [x, hx] of [[xa, 1], [xa + 2 * r, -1]]) { const zm = free ? zb : z0 + 3;
      B.quad([x, yBase, z0], [x, ys, z0], [x, ys, zm], [x, yBase, zm], [mouth, mouth, inB, inB], K.BRICK, [hx, 0, 0]);
      if (!free) B.quad([x, yBase, zm], [x, ys, zm], [x, ys, zb], [x, yBase, zb], inB, K.BRICK, [hx, 0, 0]); }
    if (free) { B.box(xp, yBase, z0, xa, yTop - 0.35, zb, pier, K.BRICK, 'XZ'); continue; }
    const yf = yBase + 0.02;
    B.quad([xa, yf, z0 - 0.25], [xa + 2 * r, yf, z0 - 0.25], [xa + 2 * r, yf, z0 + 1.4], [xa, yf, z0 + 1.4], [floorM, floorM, floorMid, floorMid], K.PAVE, [0, 1, 0]);
    B.quad([xa, yf, z0 + 1.4], [xa + 2 * r, yf, z0 + 1.4], [xa + 2 * r, yf, z0 + 4.2], [xa, yf, z0 + 4.2], [floorMid, floorMid, floorB, floorB], K.PAVE, [0, 1, 0]);
    B.quad([xa, yf, z0 + 4.2], [xa + 2 * r, yf, z0 + 4.2], [xa + 2 * r, yf, zb], [xa, yf, zb], floorB, K.PAVE, [0, 1, 0]);
    B.quad([xa, yBase, zb], [xa + 2 * r, yBase, zb], [xa + 2 * r, ys + r, zb], [xa, ys + r, zb], [backLo, backLo, backHi, backHi], K.BRICK, N);
    vaultThings(B, n, j, xa, yBase, z0, 0.9);
    if (j % 6 === 5) await yieldNow();
  }
  // the last pier against the palace, the cornice, a string course under it, and the low lip over all
  const xe = FRONT_X0 + BAYS * BAY;
  B.box(xe, yBase, zp, M.GX1, yTop - 0.35, z0, pier, K.BRICK, 'xz');
  B.box(FRONT_X0, yTop - 0.62, z0 - 0.32, M.GX1, yTop - 0.5, z0, shade(COL.brickPale, tone * 1.04), K.BRICK, 'xyYz');
  B.box(FRONT_X0, yTop - 0.35, z0 - 0.42, M.GX1, yTop - 0.12, z0, shade(COL.brickRed, tone), K.BRICK, 'xyz');
  B.box(FRONT_X0, yTop - 0.12, z0 - 0.3, M.GX1, yTop + 0.45, z0 + 0.5, shade(COL.brickPale, tone), K.BRICK, 'xyYzZ');
}

// R8, THE STAIR'S RIVER WALL AS THE GARDEN'S FACE (INVENTED; typed, the same on every seed). Each planter's length
// of the wall from the second on (the first is the low bed at the stair's foot: STRIP_FOOT) carries, under its
// parapet's coping, A PLAIN COURSE OF BLUE GLAZED BRICK two courses high (BAND: [its
// foot over the planter's earth, its head, proud]) and A MOULDED COPING of two courses stepping out (COPE: [foot,
// head, proud] each; the upper of worn brick, across the parapet's whole thickness). No figure, no animal, no
// rosette, nothing lettered; no spout on this wall. The buttresses stand as they stood, in the shade map's light.
export const RIVER_WALL = { BAND: [0.3, 0.3 + 2 * BRICK.H, 0.03], COPE: [[0.3 + 2 * BRICK.H, 0.585, 0.06], [0.585, 0.76, 0.13]] };
// THE STRIP'S FIRST BED, AT THE STAIR'S FOOT (r8; typed, the same on every seed). The strip's first planter's length
// (z 0 to PLANTER_LEN) lies where one comes from the landing onto the stair's foot, and the eye's way crosses its
// north end. It is A LOW BED IN THE LANDING'S PAVING: its earth a hand over the paving (BED), a kerb of brick on edge
// at its north end (KERB), the river wall beside it no higher than its plinth course (WALL: no parapet, no glazed
// course, no coping; those begin with the second planter, whose north side stands whole over the bed), and the
// stair's cheek beside it stepped in CHEEKS lengths, each level with the stair at its upper end. All are heights over
// the quay's paving. So every part of it, as a whole body, keeps the clear air law's 2.0 m from the lens's place
// whatever the turn; the count prints each part (stripFootBoxes gives the same boxes to the build and to the count).
// No plant stands in it (the palms begin with the second planter, as they did).
export const STRIP_FOOT = { BED: 0.1, KERB: 0.35, WALL: 0.7, CHEEKS: 4 };
export function stripFootBoxes() {
  const q = M.QUAY_Y, x0 = M.STRIP_X0, x1 = M.STAIR_X0, F = STRIP_FOOT, L = PLANTER_LEN, dz = L / F.CHEEKS;
  const out = [['earth', x0 + 0.4, q, 0.3, x1 - 0.3, q + F.BED, L], ['kerb', x0 + 0.4, q, 0, x1 - 0.3, q + F.KERB, 0.3],
    ['wall', x0, q, 0, x0 + 0.4, q + F.WALL, L], ['back', x0 + 0.4, q, L, x1 - 0.3, planterY(L) - 0.6, L + 0.3]];
  for (let k = 0; k < F.CHEEKS; k++) out.push(['cheek', x1 - 0.3, q, k * dz, x1, stairY((k + 1) * dz), (k + 1) * dz]);
  return out;
}
// the planters of the palm strip: level boxes 4 m long that step up with the stair; their tops
export const PLANTER_L = PLANTER_LEN, BAND_X0 = M.STAIR_X1, BAND_X1 = M.STAIR_X1 + M.PIER_W + M.ARCH_SPAN;
export const planterY = (z) => stairY(Math.floor(z / PLANTER_L) * PLANTER_L + PLANTER_L / 2) + 0.35;

// A GREAT POT of fired clay standing on paving (r8): POT_SHAPE's rings [radius as a share of POT_TREE.R, height as a
// share of POT_TREE.H] turned in POT_SIDES sides, a rolled rim, dark watered earth within, and its contact shade on
// the paving (a fan of the paving's own kind, dark at the pot's foot)
const POT_SHAPE = [[0.6, 0], [0.96, 0.4], [1, 0.66], [0.78, 0.92], [0.9, 1]], POT_SIDES = 8;
export function pot(B, x, y, z, pave = 1.16) {
  const R = POT_TREE.R, H = POT_TREE.H, c = COL.clay, UP = [0, 1, 0];
  { const r = 1.75 * R, mid = shade(COL.pave, pave * 0.5), rim = shade(COL.pave, pave), n = 8, yy = y + 0.012;
    for (let i = 0; i < n; i++) { const a0 = (i / n) * Math.PI * 2, a1 = ((i + 1) / n) * Math.PI * 2; B.tri([x, yy, z], [x + Math.cos(a1) * r, yy, z + Math.sin(a1) * r], [x + Math.cos(a0) * r, yy, z + Math.sin(a0) * r], [mid, rim, rim], K.PAVE, UP); } }
  for (let i = 0; i + 1 < POT_SHAPE.length; i++) { const [r0, h0] = POT_SHAPE[i], [r1, h1] = POT_SHAPE[i + 1]; limb(B, [x, y + h0 * H, z], [x, y + h1 * H, z], r0 * R, r1 * R, POT_SIDES, shade(c, i === POT_SHAPE.length - 2 ? 1.12 : 0.92 + 0.06 * i)); }
  { const r = 0.84 * R, yy = y + 0.95 * H; for (let i = 0; i < POT_SIDES; i++) { const a0 = (i / POT_SIDES) * Math.PI * 2, a1 = ((i + 1) / POT_SIDES) * Math.PI * 2; B.tri([x, yy, z], [x + Math.cos(a1) * r, yy, z + Math.sin(a1) * r], [x + Math.cos(a0) * r, yy, z + Math.sin(a0) * r], COL.earthWet, K.EARTH, UP); } }
}
// the standing garden: terraces, fronts, stair, strip, river wall, water house, court, walk, parapet, gate block
export async function buildGardenStructure(B, yieldNow) {
  const tones = [1.0, 0.97, 1.03, 0.96, 1.0];
  for (let n = 0; n < 5; n++) {
    const z0 = n * 24, yTop = M.TER_Y[n], yBase = n === 0 ? M.QUAY_Y : M.TER_Y[n - 1];
    await archedFront(B, n, z0, yBase, yTop, tones[n], yieldNow);
    const wall = shade(COL.brick, tones[n]), pale = shade(COL.brickPale, tones[n]);
    {
      // THE PLANTED BAND beside the flight (INVENTED): the terrace's west end, one bay wide (x 17 to 21.4), steps up
      // with the stair in four planters; the terrace's own west wall stands behind it, and the arched front begins at
      // that wall (its first pier at x 21.4), so that from every landing the band lies open with its beds
      for (let k = 0; k < 4; k++) {
        const za = z0 + (k ? k * PLANTER_L : FREE_ARCH_D), zb = z0 + (k + 1) * PLANTER_L, yp = planterY(za);
        B.quad([BAND_X0 + 0.3, yp, za + 0.3], [BAND_X1, yp, za + 0.3], [BAND_X1, yp, zb], [BAND_X0 + 0.3, yp, zb], COL.earth, K.EARTH, [0, 1, 0]);
        B.box(BAND_X0, stairY(za), za, BAND_X0 + 0.3, yp + 0.25, zb, pale, K.BRICK, 'xXYzZ');
        B.box(BAND_X0 + 0.3, yp - 1.1, za, BAND_X1, yp + 0.25, za + 0.3, pale, K.BRICK, 'YzZ');
        if (yTop > yp + 0.05) B.quad([BAND_X1, yp, za], [BAND_X1, yp, zb], [BAND_X1, yTop, zb], [BAND_X1, yTop, za], wall, K.BRICK, [-1, 0, 0]);
      }
      B.box(BAND_X1 - 0.2, yTop, z0 + 0.5, BAND_X1 + 0.25, yTop + 0.3, z0 + 16, pale, K.BRICK, 'xXYzZ');
      // the passage of the free arch: its top (which carries the lip channel to the stair-side spout), the strip of
      // its south face and of its west flank under the top
      B.quad([BAND_X0, yTop, z0 + 0.5], [BAND_X1 + 0.25, yTop, z0 + 0.5], [BAND_X1 + 0.25, yTop, z0 + FREE_ARCH_D], [BAND_X0, yTop, z0 + FREE_ARCH_D], shade(COL.pave, 1.02), K.PAVE, [0, 1, 0]);
      B.quad([BAND_X0, yTop - 0.35, z0 + FREE_ARCH_D], [BAND_X1, yTop - 0.35, z0 + FREE_ARCH_D], [BAND_X1, yTop, z0 + FREE_ARCH_D], [BAND_X0, yTop, z0 + FREE_ARCH_D], pale, K.BRICK, [0, 0, 1]);
      B.quad([BAND_X0, yTop - 0.35, z0], [BAND_X0, yTop - 0.35, z0 + FREE_ARCH_D], [BAND_X0, yTop, z0 + FREE_ARCH_D], [BAND_X0, yTop, z0], pale, K.BRICK, [-1, 0, 0]);
    }
    await yieldNow();
  }
  // the stair: steps of about 16 cm, landings paved
  const tread = shade(COL.pave, 1.12), riser = shade(COL.pave, 0.9), X0 = M.STAIR_X0, X1 = M.STAIR_X1;
  for (let k = 0; k < 5; k++) {
    const za = k * 24, rise = STAIR_Y[k + 1] - STAIR_Y[k], steps = stairSteps(k), dz = M.FLIGHT / steps, dy = rise / steps;
    for (let s = 0; s < steps; s++) {
      const z = za + s * dz, y = STAIR_Y[k] + s * dy;
      B.quad([X0, y, z], [X1, y, z], [X1, y + dy, z], [X0, y + dy, z], riser, K.PAVE, [0, 0, -1]);
      B.quad([X0, y + dy, z], [X1, y + dy, z], [X1, y + dy, z + dz], [X0, y + dy, z + dz], tread, K.PAVE, [0, 1, 0]);
    }
    B.quad([X0, STAIR_Y[k + 1], za + 16], [X1, STAIR_Y[k + 1], za + 16], [X1, STAIR_Y[k + 1], za + 24], [X0, STAIR_Y[k + 1], za + 24], shade(COL.pave, 1.16), K.PAVE, [0, 1, 0]);
  }
  // (r8) THE POTS of the landings' river-side corners (see POT_TREE): fired clay, a metre high, their shade on the paving
  for (const [x, y, z] of potPlaces()) pot(B, x, y, z);
  await yieldNow();
  // the palm strip (x 5 to 8) in stepped planters, and the river wall below it, sheer to the quay, with shallow buttresses
  const sx0 = M.STRIP_X0, sx1 = M.STAIR_X0;
  // (r8) the strip's first planter's length is the low bed at the stair's foot (STRIP_FOOT): its earth, its north
  // kerb, the plinth-high river wall, the stair's stepped cheek, and the second planter's north side over the bed
  for (const [what, xa, ya, za, xb, yb, zb] of stripFootBoxes()) {
    if (what === 'earth') B.box(xa, ya, za, xb, yb, zb, COL.earth, K.EARTH, 'Y');
    else if (what === 'wall') B.box(xa, ya, za, xb, yb, zb, COL.brick, K.BRICK, 'XYzZ');
    else B.box(xa, ya, za, xb, yb, zb, COL.brickPale, K.BRICK, what === 'back' ? 'z' : what === 'kerb' ? 'XYzZ' : 'xXYzZ');
  }
  for (let z = PLANTER_L; z < M.HOUSE_Z0; z += PLANTER_L) {
    const y = planterY(z), z1 = z + PLANTER_L;
    B.box(sx0 + 0.4, y - 1.2, z + 0.3, sx1 - 0.3, y, z1 - 0.3, COL.earth, K.EARTH, 'Y');
    // the curb round the planter and the wall's parapet on the river side
    B.box(sx1 - 0.3, Math.min(stairY(z), y - 0.6), z, sx1, y + 0.25, z1, COL.brickPale, K.BRICK, 'xXYzZ');
    B.box(sx0 + 0.4, y - 0.6, z, sx1 - 0.3, y + 0.25, z + 0.3, COL.brickPale, K.BRICK, 'YzZ');
    B.box(sx0 + 0.4, y - 0.6, z1 - 0.3, sx1 - 0.3, y + 0.25, z1, COL.brickPale, K.BRICK, 'YzZ');
    // (the same faces in the same order: the river face is the wall of the row of buttresses and carries its kind)
    B.box(sx0, M.QUAY_Y, z, sx0 + 0.4, y + 0.7, z1, COL.brick, pilKind('STAIR', 'x', 2 * PLANTER_L, true), 'x'); B.box(sx0, M.QUAY_Y, z, sx0 + 0.4, y + 0.7, z1, COL.brick, K.BRICK, 'XzZ');
    // (r8, the garden's face to the river; see RIVER_WALL) the glazed course and the coping's two courses
    { const R = RIVER_WALL; B.box(sx0 - R.BAND[2], y + R.BAND[0], z, sx0, y + R.BAND[1], z1, COL.glaze, K.GLAZE, 'xyzZ');
      B.box(sx0 - R.COPE[0][2], y + R.COPE[0][0], z, sx0, y + R.COPE[0][1], z1, COL.brickPale, K.BRICK, 'xyzZ');
      B.box(sx0 - R.COPE[1][2], y + R.COPE[1][0], z, sx0 + 0.45, y + R.COPE[1][1], z1, shade(COL.brickPale, 1.06), K.WORN, 'xXyYzZ'); }
    if ((z / PLANTER_L) % 2 === 1) {
      // a buttress: PILASTER.STAIR wide and proud (1.4 m, half a metre), its head stepped in under the cornice; one
      // to every second planter; its faces carry K.PIL (a part of the row finer than the picture goes into its mean)
      const [bw, bd] = PILASTER.STAIR, bk = pilKind('STAIR', 'x', 2 * PLANTER_L);
      B.box(sx0 - bd, M.QUAY_Y, z - bw / 2, sx0, y - 1.4, z + bw / 2, COL.brickPale, bk, 'xYzZ');
      B.box(sx0 - 0.25, y - 1.4, z - 0.5, sx0, y - 0.6, z + 0.5, COL.brickPale, bk, 'xYzZ');
    }
  }
  B.box(sx0 - 0.3, M.QUAY_Y, 0, sx0, M.QUAY_Y + 0.7, M.HOUSE_Z0, COL.brickRed, K.BRICK, 'xYz');
  await yieldNow(2);
}

// ---------------------------------------------------------------- the water's way (a law of the place, read by the build and by the count)
// Lifted unseen in the shut house; from its foot the head channel crosses the stair's top landing, turns north along the
// court's east side and runs east along z 104; on every terrace a channel under its lip feeds brick spouts every 12 m,
// each set on the middle of the pier nearest to it (and one at its west end beside the stair), which drip to the
// channel at the foot of the front below; cross channels
// (over arch middles: FEEDER_X) carry the water north across each terrace to the next lip. The lowest spouts drip
// into the canal.
export const SPOUT_X = []; for (let x = 23; x < 124; x += M.SPOUT_EVERY) SPOUT_X.push(FRONT_X0 + Math.round((x - FRONT_X0 - M.PIER_W / 2) / BAY) * BAY + M.PIER_W / 2);
// the water house's door on the landing: [z0, z1, height]
export const HOUSE_DOOR = [116.0, 117.4, 2.3];
export const SPOUT_REACH = 0.8, LIP_CH = 1.05, FOOT_CH = 24 - SPOUT_REACH, WALK_W0 = 19.3, WALK_W1 = 22.1;
// the head channel leaves the house's foot east along z 114, turns north at x 29 and runs east along z 104. The
// turn's place is the court's own plan: x 29 lies in the paved way between the court's two beds (their near ends
// at x 28.3 and x 31.4), a tenth of a metre east of the middle of the front's second arch (x 28.9), so the channel
// crosses the court where its paving is open. (r8a: the short branch that left it south to the court's dipping
// basin, under the gardeners' lean-to, is taken out with them: it fed that basin and nothing else.)
export const HEAD_TURN_X = 29;
// the top walk's paving reaches WALK_HALF either side of its middle line; the south parapet's coping lies PARAPET_TOP
// over the top terrace
export const WALK_HALF = 2, PARAPET_TOP = 1.05;
// every straight piece of channel: [x0, z0, x1, z1, y] (water flows from the first end to the second)
export function channelRuns() {
  const runs = [], H = M.HEAD_CHANNEL_Z;
  runs.push([M.HOUSE_X1, 114, HEAD_TURN_X, 114, 23], [HEAD_TURN_X, 114, HEAD_TURN_X, H, 23], [HEAD_TURN_X, H, 126, H, 23]);
  for (let n = 4; n >= 0; n--) {
    const z0 = n * 24, y = M.TER_Y[n];
    // the feeders north to the lip channel, the lip channel, and (below the top) the foot channel that takes the drips
    const from = n === 4 ? H : z0 + FOOT_CH;
    for (const x of FEEDER_X) if (n < 4 || x > HEAD_TURN_X) runs.push([x, from, x, z0 + LIP_CH, y]);
    runs.push([126, z0 + LIP_CH, WEST_SPOUT_X, z0 + LIP_CH, y]);
    if (n < 4) runs.push([WEST_SPOUT_X + BASIN.half, z0 + FOOT_CH, 126, z0 + FOOT_CH, y]);
  }
  return runs;
}
// THE SPOUT BESIDE THE STAIR: at every terrace's west end, on the pier at the stair's edge (5.4 m east of the
// stair's middle line, which the lens flies as far as the fourth flight; the top terrace's spout is the nearest: its
// mouth 4.1 m from the line where the line has left the stair's middle for the court, the count's box for it 3.84
// m), a spout whose water hangs as a thread to a brick basin at the landing's side; the foot channel of the
// terrace below begins at that basin (the first terrace's basin stands on the landing platform)
// (r8: the basin stands before the end pier's base, a brick basin BASIN.half either way, its walls BASIN.wall
// thick and BASIN.rim high, its water BASIN.water over the floor; the spout stands WEST_REACH out of the front's
// line, so that its thread lands in the basin's middle; the foot channel leaves the basin's east side)
export const WEST_SPOUT_X = FRONT_X0 + M.PIER_W / 2, BASIN = { half: 0.5, rim: 0.36, water: 0.28, wall: 0.14 }, WEST_REACH = 0.25 + END_PIER.BASE[1] + BASIN.half;
