export const westBedX1 = () => FEEDER_X[0] - M.CHANNEL_W / 2 - 0.13 - 0.02;
// THE DIPPING BASINS of the top walk (INVENTED): where a feeder leaves the head channel northward, a small spout on
// the channel's south curb runs into a brick basin sunk in the ground beside the walk (DIP), where the water
// carriers fill their jars
export const DIP = { half: 0.4, depth: 0.32, z: M.HEAD_CHANNEL_Z + 0.62 };
