// stands parted JAR_PART either side of the basin's middle, for the basin's rim and the jar
export const JAR_OFF = [0.95, 0.52], JAR_PART = 1.45;
export const dipX = () => FEEDER_X.filter((x) => x > HEAD_TURN_X + 4);
