  const span = REACH_Z1 - REACH_Z0, s = (((b.z0 - REACH_Z0 + RIVER_V * t) % span) + span) % span, z = REACH_Z0 + s;
  out[0] = laneX(b, z) + b.off + LANE_WEAVE * Math.sin(0.021 * t + b.wob); out[1] = z; out[2] = b.a0 + b.spin * t;
  out[3] = b.size * smoothstep(0, REACH_EASE, s) * (1 - smoothstep(span - REACH_EASE, span, s));
