// No gardener works on the top terrace or on terrace 4: the top is the wood, and under its trees there is no bed to
// tend (a floor of fallen needles and clipped rows); terrace 4's alley lies under the top walk's line.
export const GARDENER_J0 = ALLEY_MID_J, GARDENER_ROW = (HERB_ROWS[2] + HERB_ROWS[3]) / 2;
