//   THE SLUICE (SLUICE, SLUICE_X) in the head channel SLUICE.OUT from the water house's outlet: two brick cheeks, a
//   board of planks set in its slot between them, a lifting bar, a wet line on the brick under it; it has no
//   keeper (r6: the place is beside the stair's last landing).
export const COURT_PANEL = { X0: 17.2, DX: 2.77, Z0: 96.6, DZ: 2.81, W: 0.33 };
const panelBox = (i0, k0, i1, k1) => [COURT_PANEL.X0 + i0 * COURT_PANEL.DX + COURT_PANEL.W, COURT_PANEL.Z0 + k0 * COURT_PANEL.DZ + COURT_PANEL.W, COURT_PANEL.X0 + (i1 + 1) * COURT_PANEL.DX, COURT_PANEL.Z0 + (k1 + 1) * COURT_PANEL.DZ];
export const COURT_BED_H = 0.3;
export const COURT_BEDS = [panelBox(2, 0, 3, 1), panelBox(5, 0, 5, 1), panelBox(2, 5, 3, 5), panelBox(5, 5, 5, 7),
  [panelBox(3, 7, 3, 7)[0], 114 + M.CHANNEL_W / 2 + 0.3, panelBox(3, 7, 3, 7)[2], panelBox(3, 7, 3, 7)[3]], panelBox(2, 7, 2, 7)];
export function flapsOf(a) {
  const out = [], top = a.base + AWNING_H;
  if (a.edge === 'w') for (let z = a.z0; z < a.z1 - 0.1; z += 1.2) out.push({ x: a.x0, y: top, z: z + 0.6, ax: 0, w: FLAP_W, h: FLAP_H });
  else for (let x = a.x0; x < a.x1 - 0.1; x += 1.2) out.push({ x: x + 0.6, y: top - 0.3, z: a.z0, ax: Math.PI / 2, w: FLAP_W, h: FLAP_H - 0.05 });
  return out;
}

// ---------------------------------------------------------------- THE FLIGHT'S LAW (read by the world and by the count)
// THE PACES in metres a second, each the constant of its own stretch:
//   RIVER    the way down over the river: the glide from the mouth and the reach to the reed bar (no craft is declared)
//   LANDING  over the quay's edge and the landing platform, slow enough to read the quay
//   STAIR    the long stair: one steady climb (the flights are alike; what is looked at lies beside them)
//   COURT    the stair's head and the court: the slowest of the flight, for the looks out from the garden's top
//   WALK     the walk under the cedars to the door
// No duration is typed: it is the sum of the stretches' times at these paces (makeFlight().duration).
// (PACE is THE OWNER'S RIDER: the river at 12 m/s, the stair and the walk at their pace, about 373 m in 38.4 s, as
// the owner answered; no round changes a pace's number. ROUND 8 MOVED ONE STRETCH'S END: the stair's pace has fallen
// to the court's at the mark leave (the way's 246.5 m, where the line has left the stair's middle on the fourth
// flight) and no longer at the last flight's foot (268.0 m), because the turn begins on the fourth flight. The
// flight takes 38.37 s as built (printed 38.4); by round 7's law on this line it would take 37.85 s. The owner
// took the mark as built: its word of 14:11 UTC on 11 Oct 2026.)
export const PACE = { RIVER: 12, LANDING: 8.5, STAIR: 10, COURT: 6.9, WALK: 10.7, REF: 10 };
// the walk's east end: the head of the two steps down to the door's sill
export const WALK_END_X = 125.6;
// THE ONE LOOK of the flight and its weight (the share of the angle between the way ahead and the thing looked at
// that the gaze turns: see the engine's looks with arc)
export const LOOK_WEIGHT = 0.75;
// THE TWO HELD LOOKS INTO THE TERRACES (terraces counted from 0): the low one into terrace 2 of the orchard, whose
// first plot beside the stair is an open one (herb beds, the vines on their frame, date palms), so that the eye
// goes deep into it between the fig row at the lip and the walk's row in blossom; the high one into terrace 4, the
// wood's skirt and the last below the top, where the stair slows to the court's pace
export const ALLEY_LOW = 1, ALLEY_HIGH = 3;
// how far out on its bearing the look's point is handed to the engine
export const LOOK_FAR = 400;
// THE THINGS LOOKED AT, each a standing place found from its own measures
// (LOOK_FRONT_J: the pier line of the terraces' fronts on which the stair's look lies: the first line east of the
// planted band whose pier carries a tree of the lip's row behind it on every terrace, the one the top terrace's
// rows begin on)
export const LOOK_FRONT_J = TOP_J0;
export function lookPlaces() {
  const walkMid = (WALK_W0 + WALK_W1) / 2;
  return {
    // THE GARDEN WHOLE, from the height of the way in: the middle of the garden's plan at the middle terrace's
    // level (the five floors lie about it, two below and two above)
    garden: [(M.GX0 + M.GX1) / 2, M.TER_Y[2], (M.GZ0 + M.GZ1) / 2],
    // THE RIVER FRONT'S PALMS: the middle of the palm strip beside the stair (half way between its first planter and
    // the water house), at the middle of a palm's trunk over the planter there. From the river north of the
    // limestone wall it lies to the right of the wall's river end, with the stair's foot before it
    front: [STRIP_PALM_X, planterY((PLANTER_L + M.HOUSE_Z0) / 2) + 6, (PLANTER_L + M.HOUSE_Z0) / 2],
    // THE PLANTED FRONT OF EACH TERRACE ABOVE THE FIRST (terraces 1 to 4, counted from 0): the top of its arched
    // front at pier line LOOK_FRONT_J, where the lip's row of trees stands over the coping
    fronts: [1, 2, 3, 4].map((n) => [pierX(LOOK_FRONT_J), M.TER_Y[n] + EYE, n * M.TER_DEPTH]),
    // one for each of the four lower terraces: the far end of its walk, where the walk meets the palace wall behind
    // the end grove, at eye height over the terrace (the look runs down the whole alley beside the foot channel)
    terrace: [0, 1, 2, 3].map((n) => [M.GX1, M.TER_Y[n] + EYE, n * M.TER_DEPTH + walkMid]),
    // OVER THE GARDEN TO THE PLAIN: the plain's north canal (PLAIN_CANALS[1]) a third of the way from its south end
    // to where it meets the field canal: the worked country's long line of water and palms north-east of the garden.
    // From the court's north side it lies out over the lower terraces' crowns. (ROUND 8 MOVED THIS PLACE: round 7's
    // was the meeting itself, 533 m further north. The third is a typed share of our own, and its reason is the
    // flown line: at the top terrace's lip the gaze toward round 7's place would stand 74.1 degrees off the way,
    // against the limit of 75; toward this one it stands 58.3. From the lip this place bears 51.0 degrees east of
    // north; round 7's bore 29.9. The owner took the place as built: its word of 14:11 UTC on 11 Oct 2026.)
    north: [PLAIN_CANALS[1][0], 0, PLAIN_CANALS[1][3] + (FIELD_CANAL_Z - PLAIN_CANALS[1][3]) / 3],
    // the blue gate: the top of the rear gate's curtain, where its crest stands
    gate: [FAR_GATE.X, STREET.Y + FAR_GATE.REAR.H, FAR_GATE.REAR.Z0],
    door: [M.DOOR[0], M.DOOR[1], M.DOOR[2]],
  };
}
// path: the route (makeRoute()). Gives the MARKS (metres along the route where the lens comes abreast of a standing
// thing, each by that thing's own constant), the speed at every metre, the duration, the pace the engine wants, and
// the look: its window (from a mark to a mark, its ramp the way between two marks) and its look-at place.
export function makeFlight(path) {
  const L = path.length, ss = smoothstep, D = M.TER_DEPTH;
  // (the line's places every quarter metre are taken once; every mark is the first of them that passes its test,
  // looked for from a mark found before it, which is itself one of these places)
  const STEP = 0.25, places = []; for (let d = 0; d <= L; d += STEP) places.push(path.posAtDist(d).clone());
  const where = (test, from = 0) => { const i0 = from / STEP;
    if (Number.isInteger(i0)) { for (let i = i0; i < places.length; i++) if (test(places[i])) return i * STEP; return L; }
    for (let d = from; d <= L; d += STEP) if (test(path.posAtDist(d))) return d; return L; };
  const m = {};
  m.mouthN = where((p) => p.z > MOUTH_N[1]);                             // the far bank's first canal mouth (the flight begins south of it: 0)
  m.moatN = where((p) => p.z > BANK_S);                                  // the moat's north bank
  m.barS = where((p) => p.z > MOUTH_BAR.Z1);                             // the south end of the reed bar in the moat's mouth
  m.wallN = where((p) => p.z > -(M.CANAL_W + M.WALL_T));                 // the limestone wall's north face
  m.wallS = where((p) => p.z > -M.CANAL_W);                              // its south face
  m.quay = where((p) => p.x > 0);                                        // the quay's edge
  m.stair = where((p) => p.z > M.GZ0, m.quay);                           // the stair's foot
  m.land = [0, 1, 2, 3].map((k) => where((p) => p.z > k * D + M.FLIGHT));   // the north edge of each landing
  m.foot = [0, 1, 2, 3, 4].map((k) => where((p) => p.z > k * D, m.quay));   // the foot of each flight
  m.bandE = where((p) => p.x > BAND_X1, m.foot[4]);                      // the line is east of the planted band's east wall: with r8's line, where it comes over the top terrace's lip
  m.courtE = where((p) => p.x > M.COURT_X1, m.foot[4]);                  // the court's east edge
  m.gap0 = where((p) => p.x > GAP_X0, m.foot[4]); m.gap1 = where((p) => p.x > GAP_X1, m.foot[4]);   // the gap in the south row
  m.feeder = FEEDER_X.map((x) => where((p) => p.x > x, m.foot[4]));       // where the walk crosses each feeder channel's line
  m.cedarE = where((p) => p.x > pierX(GAP_J[1] + 2), m.foot[4]);         // the first pair of cedars east of the gap
  m.walkE = where((p) => p.x > WALK_END_X, m.foot[4]);                   // the walk's east end (the steps' head)
  m.doorSeen = m.feeder[FEEDER_J.indexOf(DOOR_SEEN_J)];                  // the gap's east dipping basin abeam (where the next world is first seen in the door)
  m.eye = [0, 1, 2, 3].map((k) => where((p) => p.y > M.TER_Y[k], m.stair));   // where the eye's height passes each lower terrace's level (its floor comes into sight)
  m.half = [0, 1, 2, 3].map((k) => where((p) => p.z > k * D + M.FLIGHT / 2, m.stair));   // the middle of each flight
  m.leave = where((p) => p.x > (M.STAIR_X0 + M.STAIR_X1) / 2 + 0.25, m.land[2]);   // where the line has left the stair's middle by a quarter of a metre (on the fourth flight)
  m.edge = m.foot[4];                                                    // the court's north edge: the line crosses the top terrace's front (its lip and parapet lie under the eye)
  m.rowN = where((p) => p.z > M.WALK_Z - M.ROW_OFF, m.foot[4]);          // the line crosses the north row's own line, between the court's cedar and the row's first
  m.join = m.feeder[1];                                                  // the line is on the walk's middle: the first dipping basin abeam
  m.winS = where((p) => p.x > (pierX(WINDOW_S_J[0] + 1) + pierX(WINDOW_S_J[1])) / 2, m.foot[4]);   // the middle of the south window abeam
  m.lastCedar = where((p) => p.x > pierX(END_J - 2), m.foot[4]);         // the last pair of the walk's cedars
  // (MARKS THAT NO LAW OF THE FLIGHT OR THE WORLD READS: wallN, gap0, eye, rowN, join. They are measures of the line
  // at named places, kept for the count and for the words at the head; nothing is built, timed or aimed by them.)
  // THE SPEED at d metres: the river's pace down to the reed bar's south end, falling to the landing's pace at the
  // quay's edge; rising to the stair's pace from the stair's foot to the first landing; falling to the court's pace
  // from the third landing to where the line leaves the stair's middle; the court's pace over the fourth terrace's
  // corner, the edge and the court to the court's east edge; rising to the walk's pace across the gap
  const speedAt = (d) => PACE.RIVER + (PACE.LANDING - PACE.RIVER) * ss(m.barS, m.quay, d) + (PACE.STAIR - PACE.LANDING) * ss(m.stair, m.land[0], d)
    + (PACE.COURT - PACE.STAIR) * ss(m.land[2], m.leave, d) + (PACE.WALK - PACE.COURT) * ss(m.courtE, m.gap1, d);
  let T = 0; const step = 0.25, clock = [0]; for (let d = 0; d < L; d += step) { T += Math.min(step, L - d) / speedAt(d + step / 2); clock.push(T); }
  const duration = Math.round(T * 10) / 10, pace = (u) => speedAt(u * L) / PACE.REF;
  const timeAt = (d) => { const x = clamp(d, 0, L) / step, i = Math.min(clock.length - 2, Math.floor(x)); return clock[i] + (clock[i + 1] - clock[i]) * (x - i); };
  // THE LOOK is on from the far bank's first canal mouth (which lies north of where the flight begins, so from the
  // first metre) to the walk's east end. THE ENGINE TAKES ONE FADE FOR BOTH ENDS OF A LOOK: its length is the door
  // end's own measure, the way from the last pair of the walk's cedars to the steps' head (10.75 m): by then the
  // look lies on the door, straight ahead. At the entry the same length is laid at no standing thing (the engine's
  // one fade, borrowed); since r8a the look it brings in there lies straight ahead, on the entry frame's own
  // direction, and the turn to the garden is the look's own eased law (next lines).
  // THE LOOK-AT PLACE at d metres, by the visitor's own reasons:
  //   ON THE WAY DOWN (r8a, THE EASED LOOK AT THE MOUTH; the owner, 14:34 UTC on 11 Oct 2026): AT THE MOUTH THE LOOK
  //   LIES ON THE ENTRY FRAME'S OWN DIRECTION (F0: level, on the bearing of the line's first tangent, which is the
  //   engine's path.frameAt(0): what a camera carried in through a door is looking along), and from there it COMES
  //   DOWN TO THE GARDEN WHOLE (the middle of its plan at the middle terrace's level: the five floors lie open about
  //   it) BY ONE EASED LAW OF THE WAY'S METRES: seen from the line's own place at d, the bearing turns from the one
  //   toward the other by the eased share (ss) of the angle between them along the way from the mouth (the mark
  //   mouthN, the flight's first metre) to where the moat's north bank is abeam (the mark moatN, 32.5 m). It reads d
  //   between those two places and nothing else: no clock, no speed, no seed, no still. THE LINE IS UNTOUCHED. THE
  //   REASON: round 8's look lay on the garden whole from the first metre, 19.6 degrees off the entry frame, and
  //   the engine brought its weight in over the first 11 to 15 m: a camera arriving at a carried speed of 60 m a
  //   second turned at 31.6 degrees a second 12 m in (tools/sw/camarrive.mjs); by this law it turns at 22.0 at the
  //   most, and the gaze's own fastest turn on the way down falls from 25.4 to 12.3 degrees a second. From the
  //   mark moatN on the law is round 8's to the letter: the look lies on the garden whole, and from there to the
  //   reed bar's south
  //   end it comes down to the river front's palms: one looks at the landing one is bound for, and the limestone
  //   wall's river end is passed east of the way, abeam and falling astern; it lies there until the wall's south
  //   face is abeam;
  //   from there to the stair's foot it goes over to THE PLANTED FRONT of the second terrace (lookPlaces().fronts),
  //   the first that stands over the stair's own first flight, and lies on the terraces' fronts on the climb;
  //   TWO HELD LOOKS INTO THE TERRACES (ALLEY_LOW, ALLEY_HIGH: see there). The look goes over toward the alley's far
  //   end from the middle of the flight below that terrace's own to the middle of its own flight: the eased camera
  //   then lies along the alley when the eye's height passes the terrace's level and its floor comes into sight,
  //   and stays so across the landing. From the low alley it returns, from its landing's north edge to the next
  //   landing's north edge, to the planted front and the trees of the terrace next above (not to the steps'
  //   middle); from the high alley (the last below the top) it does not return:
  //   OVER THE GARDEN TO THE PLAIN: from the fourth landing's north edge the look goes over toward the plain's
  //   north canal in the north-east and is reached at the court's north edge (the stair's head: the line crosses
  //   the top terrace's front there). IT IS NOT HELD: from the edge the line heads south-east through the court's
  //   corner, and held there the gaze would stand more than 75 degrees off the way (tried: 77.8). So from the edge
  //   the look turns evenly over to the blue gate, reached where the middle of the south window is abeam, and
  //   held until the window's east end is abeam (the gap's second feeder, where its east dipping basin lies);
  //   from there to the door, reached at the first pair of cedars east of the gap.
  // (Three looks out as in round 7 and none added; but the north look's place is another than round 7's (see
  // lookPlaces), and that look is reached and not held. By measure, on a screen of 16 to 9: THE NORTH LOOK: the
  // plain's north canal lies in the picture for 19.25 m and 2.8 s where r7's line had it for 17.5 m and 2.5 s, but
  // the gaze bears 70.5 degrees east of north at its most northerly where r7's bore 44.7; THE BLUE GATE'S LOOK IS
  // LONGER: the gate lies in the picture for 35.25 m and 3.8 s where r7 had 30.25 m and 3.2 s; THE DOOR'S IS EQUAL:
  // the door lies within 15 degrees of the picture's middle for the last 46 m and 4.3 s, as in r7.)
  const Q = lookPlaces(), V = (a) => new THREE.Vector3(a[0], a[1], a[2]), q = { garden: V(Q.garden), front: V(Q.front), fronts: Q.fronts.map(V), terrace: Q.terrace.map(V), north: V(Q.north), gate: V(Q.gate), door: V(Q.door) };
  const out = new THREE.Vector3(), lo = ALLEY_LOW, hi = ALLEY_HIGH;
  // (from the stair's foot on, the look GLIDES BY BEARING: seen from the line's own place at d, the bearing turns
  // from one named place toward the next by an even share of the angle between them along the way from one mark
  // to the next, so that the turn is even; the engine is handed a point LOOK_FAR metres out on that bearing)
  const P0 = new THREE.Vector3(), TO = new THREE.Vector3(), AX = new THREE.Vector3(), along = (a, b, d) => clamp((d - a) / (b - a), 0, 1);
  const F0 = path.tangentAtDist(0, new THREE.Vector3()); F0.y = 0; F0.normalize();   // the entry frame's own direction: level, on the bearing of the line's first tangent
  const toward = (o, at, f) => { if (f <= 0) return o; TO.copy(at).sub(P0).normalize(); const ang = Math.acos(clamp(o.dot(TO), -1, 1)); if (f >= 1 || ang < 1e-5) return o.copy(TO); AX.crossVectors(o, TO).normalize(); return o.applyAxisAngle(AX, ang * f); };
  const lookAt = (d, o = out) => {
    if (d < m.moatN) { path.posAtDist(d, P0); o.copy(F0); toward(o, q.garden, ss(m.mouthN, m.moatN, d)); return o.multiplyScalar(LOOK_FAR).add(P0); }
    o.copy(q.garden).lerp(q.front, ss(m.moatN, m.barS, d)).lerp(q.fronts[0], ss(m.wallS, m.stair, d));
    if (d <= m.stair) return o;
    path.posAtDist(d, P0); o.sub(P0).normalize();
    toward(o, q.terrace[lo], along(m.half[lo - 1], m.half[lo], d));
    toward(o, q.fronts[lo + 1], along(m.land[lo], m.land[lo + 1], d));
    toward(o, q.terrace[hi], along(m.half[hi - 1], m.half[hi], d));
    toward(o, q.north, along(m.land[hi], m.edge, d)); toward(o, q.gate, along(m.edge, m.winS, d)); toward(o, q.door, along(m.feeder[2], m.cedarE, d));
    return o.multiplyScalar(LOOK_FAR).add(P0);
  };
  const from = m.mouthN, to = m.walkE, ramp = m.walkE - m.lastCedar;
  const look = { at: (time, u) => lookAt(u * L), from: from / L, to: to / L, weight: LOOK_WEIGHT, fade: ramp / (to - from), arc: true };
  return { L, marks: m, speedAt, timeAt, duration, pace, lookAt, look, looks: [look] };
}
